"""Calculate monthly cleaning-service pay from the supplied CSV files."""

import csv
import json
import re
from collections import defaultdict
from datetime import date, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from pathlib import Path


DATASET = Path("/app/dataset")
ZERO = Decimal("0")


def _read_csv(filename):
    with (DATASET / filename).open(encoding="utf-8-sig", newline="") as f:
        return list(csv.DictReader(f))


def _nonnegative_decimal(value):
    try:
        number = Decimal(value.strip())
    except (InvalidOperation, AttributeError):
        return None
    return number if number.is_finite() and number >= ZERO else None


def _billing_month(work_date, weekday):
    first = work_date.replace(day=1)
    boundary = first + timedelta(days=(weekday - first.weekday()) % 7)
    # Work before this month's first billing weekday belongs to the prior period.
    if work_date < boundary:
        first = (first - timedelta(days=1)).replace(day=1)
    return first.year, first.month


def _task_ids(value):
    # Some lists are missing an opening or closing bracket. Their integer IDs
    # remain readable; reject other unrecognizable syntax instead of guessing.
    value = value.strip()
    if not re.fullmatch(r"\[?\s*(?:\d+\s*(?:,\s*\d+\s*)*)?\]?", value):
        return []
    return [int(item) for item in re.findall(r"\d+", value)]


def answer() -> dict[str, list[int]]:
    rates = {}
    for row in _read_csv("employees.csv"):
        pesel = row["PESEL"].strip()
        rate = _nonnegative_decimal(row["hourly_rate"])
        if re.fullmatch(r"\d{11}", pesel) and rate is not None:
            rates[pesel] = rate

    task_pay = {}
    for row in _read_csv("tasks.csv"):
        payment = _nonnegative_decimal(row["pay_per_completion"])
        if row["task_id"].strip().isdigit() and payment is not None:
            task_pay[int(row["task_id"])] = payment

    shifts = []
    seen = set()
    for row in _read_csv("timesheet.csv"):
        # Duplicated shifts have distinct row IDs but identical payroll data.
        identity = tuple((key, value.strip()) for key, value in row.items()
                         if key != "id")
        if identity in seen:
            continue
        seen.add(identity)

        pesel = row["employee_id"].strip()
        if pesel not in rates:
            # An unregistered identifier cannot be reliably assigned to an
            # employee; similar-looking PESELs are not sufficient evidence.
            continue
        try:
            work_date = date.fromisoformat(row["date"].strip())
        except ValueError:
            # April 31 and June 31 have no uniquely recoverable work date.
            continue
        hours = _nonnegative_decimal(row["hours_worked"])
        if hours is None or hours > 24:
            continue

        # Reconstruct bonuses from recognized completed tasks. Unknown task
        # IDs and inconsistent recorded bonuses do not establish entitlement.
        bonus = sum((task_pay.get(task, ZERO)
                     for task in _task_ids(row["performed_tasks"])), ZERO)
        shifts.append((work_date, pesel, hours * rates[pesel] + bonus))

    if not shifts:
        return {pesel: [] for pesel in rates}

    weekday = min(work_date for work_date, _, _ in shifts).weekday()
    totals = defaultdict(lambda: defaultdict(lambda: ZERO))
    months = set()
    for work_date, pesel, pay in shifts:
        month = _billing_month(work_date, weekday)
        months.add(month)
        totals[pesel][month] += pay

    ordered_months = sorted(months)
    return {
        pesel: [int(totals[pesel][month].quantize(Decimal("1"),
                                                rounding=ROUND_HALF_UP))
                for month in ordered_months]
        for pesel in rates
    }


if __name__ == "__main__":
    with open("/app/answer.json", "w", encoding="utf-8") as f:
        json.dump(answer(), f, indent=2)
        f.write("\n")
